def _settings_for_test(**values):
    base_values = {
        "DB_INIT_MODE": "none",
        "DEPLOYMENT_MODE": "local",
        "ALLOWED_ORIGINS": "*",
        "CORS_ALLOW_CREDENTIALS": None,
        "AUTH_OWNER": "none",
        "TRUSTED_PROXY_MODE": "false",
        "STORAGE_EXPOSURE": "auto",
    }
    base_values.update(values)
    return Settings(_env_file=None, **base_values)


def _assert_raw_string_not_projected(value, raw_value: str) -> None:
    if isinstance(value, dict):
        for key, nested in value.items():
            assert key not in {"value_text", "raw_fact_value", "fact_value"}
            _assert_raw_string_not_projected(nested, raw_value)
        return
    if isinstance(value, list):
        for nested in value:
            _assert_raw_string_not_projected(nested, raw_value)
        return
    if isinstance(value, str):
        assert value != raw_value


@pytest.fixture()
def client(tmp_path, monkeypatch):
    storage_dir = tmp_path / "storage"
    monkeypatch.setattr(settings, "storage_dir", str(storage_dir))
    monkeypatch.setattr(settings, "layer3_external_local_export_dir", str(tmp_path / "external-local-export"))
    monkeypatch.setattr(settings, "layer3_internal_webhook_url", "http://127.0.0.1/layer3-internal-webhook")
    monkeypatch.setattr(settings, "layer3_internal_webhook_display_name", "test-internal-webhook")
    monkeypatch.setattr(settings, "layer3_sec_edgar_live_network_enabled", True)
    bootstrap_storage_tree(storage_dir)
    engine = create_engine(
        "sqlite:///:memory:",
        future=True,
        connect_args={"check_same_thread": False},
        poolclass=StaticPool,
    )
    Base.metadata.create_all(engine)
    SessionLocal = sessionmaker(bind=engine, autocommit=False, autoflush=False, future=True)

    def override_get_db():
        db = SessionLocal()
        try:
            yield db
        finally:
            db.close()

    app.dependency_overrides[get_db] = override_get_db
    test_client = TestClient(app)
    test_client.layer3_session_factory = SessionLocal
    try:
        yield test_client
    finally:
        app.dependency_overrides.pop(get_db, None)


def test_layer3_deployment_profile_local_defaults_enable_arelle_cutover_without_value_reveal() -> None:
    profile = _settings_for_test()

    assert profile.deployment_mode == "local"
    assert profile.allowed_origin_list == ["*"]
    assert profile.cors_allow_credentials_enabled is True
    assert profile.storage_mount_enabled is True
    assert profile.layer3_sec_edgar_arelle_fact_authority_cutover_enabled is True
    assert profile.layer3_sec_edgar_arelle_internal_value_store_enabled is False
    assert profile.layer3_sec_edgar_arelle_corpus_validation_enabled is False
    assert profile.layer3_sec_edgar_arelle_fact_authority_nonlocal_authorized is False
    assert profile.layer3_sec_edgar_arelle_value_reveal_enabled is False
    assert profile.layer3_sec_xbrl_controlled_value_reveal_submit_enabled is False

    cors_middleware = next(middleware for middleware in app.user_middleware if middleware.cls.__name__ == "CORSMiddleware")
    assert cors_middleware.kwargs["allow_origins"] == ["*"]
    assert cors_middleware.kwargs["allow_credentials"] is True
    assert any(getattr(route, "path", None) == "/storage" for route in app.routes)


def test_layer3_deployment_profile_nonlocal_accepts_proxy_owned_guardrail() -> None:
    profile = _settings_for_test(
        DEPLOYMENT_MODE="nonlocal",
        DATABASE_URL=_POSTGRES_URL,
        ALLOWED_ORIGINS="https://review.example.com, https://ops.example.com",
        AUTH_OWNER="proxy",
        TRUSTED_PROXY_MODE="true",
        LAYER3_SEC_EDGAR_ARELLE_FACT_AUTHORITY_NONLOCAL_AUTHORIZED="true",
    )

    assert profile.allowed_origin_list == ["https://review.example.com", "https://ops.example.com"]
    assert profile.cors_allow_credentials_enabled is False
    assert profile.auth_owner == "proxy"
    assert profile.proxy_identity_header == "X-Forwarded-User"
    assert profile.storage_mount_enabled is False


def test_layer3_deployment_profile_nonlocal_requires_explicit_arelle_cutover_authorization() -> None:
    with pytest.raises(ValueError, match="LAYER3_SEC_EDGAR_ARELLE_FACT_AUTHORITY_NONLOCAL_AUTHORIZED=true"):
        _settings_for_test(
            DEPLOYMENT_MODE="nonlocal",
            ALLOWED_ORIGINS="https://review.example.com",
            AUTH_OWNER="proxy",
            TRUSTED_PROXY_MODE="true",
        )


def test_layer3_deployment_profile_nonlocal_main_disables_direct_storage(tmp_path) -> None:
    code = """
import json
from main import app

cors = next(middleware for middleware in app.user_middleware if middleware.cls.__name__ == "CORSMiddleware")
print(json.dumps({
    "allow_origins": cors.kwargs["allow_origins"],
    "allow_credentials": cors.kwargs["allow_credentials"],
    "storage_mounted": any(getattr(route, "path", None) == "/storage" for route in app.routes),
}))
"""
    env = os.environ.copy()
    env.update(
        {
            "PYTHONPATH": str(BACKEND) + os.pathsep + env.get("PYTHONPATH", ""),
            "DB_INIT_MODE": "none",
            "DATABASE_URL": _POSTGRES_URL,
            "STORAGE_DIR": str(tmp_path / "storage"),
            "DEPLOYMENT_MODE": "nonlocal",
            "ALLOWED_ORIGINS": "https://review.example.com",
            "AUTH_OWNER": "proxy",
            "TRUSTED_PROXY_MODE": "true",
            "LAYER3_SEC_EDGAR_ARELLE_FACT_AUTHORITY_NONLOCAL_AUTHORIZED": "true",
        }
    )
    result = subprocess.run(
        [sys.executable, "-c", code],
        cwd=str(BACKEND.parent),
        env=env,
        text=True,
        capture_output=True,
        check=True,
    )
    body = json.loads(result.stdout.strip().splitlines()[-1])

    assert body == {
        "allow_origins": ["https://review.example.com"],
        "allow_credentials": False,
        "storage_mounted": False,
    }


