def _prepare_material(client: TestClient) -> tuple[dict, dict, dict]:
    preflight = client.post(
        "/api/v1/layer3/preflight",
        json={
            "client_request_id": "api-preflight",
            "natural_language_intent": "Review deterministic Layer 3 source material.",
            "manual_constraints": {"source_classes": ["dataset_version", "aps_content_document"]},
        },
    ).json()
    source = client.post(
        "/api/v1/layer3/source-preview",
        json={
            "client_request_id": "api-source",
            "preflight_id": preflight["preflight_id"],
            "selected_source_classes": ["dataset_version", "aps_content_document"],
        },
    ).json()
    material = client.post(
        "/api/v1/layer3/material-preview",
        json={
            "client_request_id": "api-material",
            "preflight_id": preflight["preflight_id"],
            "source_set_id": source["source_set_id"],
            "source_candidate_ids": [item["source_candidate_id"] for item in source["source_candidates"]],
            "query_basis": {"terms": ["deterministic", "source"]},
        },
    ).json()
    return preflight, source, material


def _prepare_mixed_material(
    client: TestClient,
    tmp_path,
    *,
    request_id: str,
) -> tuple[dict, dict, dict, str, str]:
    dataset_version_id = f"{request_id}-dv"
    content_id = f"{request_id}-content"
    with client.layer3_session_factory() as db:
        _seed_aps_derived_dataset_version(db, tmp_path, dataset_version_id=dataset_version_id)
        _seed_aps_content_fixture(
            db,
            tmp_path,
            run_id=f"{request_id}-run",
            target_id=f"{request_id}-target",
            content_id=content_id,
        )
        db.commit()

    preflight_response = client.post(
        "/api/v1/layer3/preflight",
        json={
            "client_request_id": f"{request_id}-preflight",
            "natural_language_intent": "Review indexed APS narrative and extracted table together.",
            "manual_constraints": {"source_classes": ["dataset_version", "aps_content_document"]},
        },
    )
    assert preflight_response.status_code == 200
    preflight = preflight_response.json()
    source_response = client.post(
        "/api/v1/layer3/source-preview",
        json={
            "client_request_id": f"{request_id}-source",
            "preflight_id": preflight["preflight_id"],
            "selected_source_classes": ["dataset_version", "aps_content_document"],
        },
    )
    assert source_response.status_code == 200
    source = source_response.json()
    material_response = client.post(
        "/api/v1/layer3/material-preview",
        json={
            "client_request_id": f"{request_id}-material",
            "preflight_id": preflight["preflight_id"],
            "source_set_id": source["source_set_id"],
            "source_candidate_ids": [item["source_candidate_id"] for item in source["source_candidates"]],
            "dataset_version_ids": [dataset_version_id],
            "aps_content_document_ids": [content_id],
            "query_basis": {"terms": ["mixed", "package"]},
        },
    )
    assert material_response.status_code == 200
    return preflight, source, material_response.json(), dataset_version_id, content_id


def _gate_b_decision_basis(candidate: dict) -> dict:
    return {
        "source_ref": candidate["source_ref"],
        "query_basis": candidate["query_basis"],
        "provenance_ref": candidate["provenance_ref"],
        "source_identity": candidate["source_identity"],
        "source_provenance": candidate["source_provenance"],
        "payload": candidate["payload"],
        "load_summary": candidate["load_summary"],
    }


def _commit_mixed_gate_b(
    client: TestClient,
    *,
    request_id: str,
    preflight: dict,
    source: dict,
    material: dict,
    approve_source_classes: set[str],
):
    decisions = []
    for candidate in material["material_candidates"]:
        approved = candidate["source_class"] in approve_source_classes
        decisions.append(
            {
                "candidate_id": candidate["candidate_id"],
                "decision": "approved" if approved else "denied",
                "operator_reason": "" if approved else "Not admitted for this mixed preview.",
                "decision_basis": _gate_b_decision_basis(candidate),
            }
        )
    return client.post(
        "/api/v1/layer3/gate-b/decision",
        json={
            "client_request_id": f"{request_id}-gate-b",
            "preflight_id": preflight["preflight_id"],
            "source_set_id": source["source_set_id"],
            "material_preview_id": material["material_preview_id"],
            "material_preview_hash": material["material_preview_hash"],
            "candidate_decisions": decisions,
            "actor": "pytest",
        },
    )


def _construct_mixed_package_set(
    client: TestClient,
    tmp_path,
    *,
    request_id: str,
) -> tuple[dict, dict, dict, dict, dict]:
    preflight, source, material, _dataset_version_id, _content_id = _prepare_mixed_material(
        client,
        tmp_path,
        request_id=request_id,
    )
    gate_b = _commit_mixed_gate_b(
        client,
        request_id=request_id,
        preflight=preflight,
        source=source,
        material=material,
        approve_source_classes={"dataset_version", "aps_content_document"},
    )
    assert gate_b.status_code == 200, gate_b.text
    preview = client.post(
        "/api/v1/layer3/package/review/preview",
        json={
            "client_request_id": f"{request_id}-package-preview",
            "session_id": gate_b.json()["session_id"],
            "material_preview_id": material["material_preview_id"],
            "material_preview_hash": material["material_preview_hash"],
        },
    )
    assert preview.status_code == 200, preview.text
    preview_body = preview.json()
    commit = client.post(
        "/api/v1/layer3/package/review/commit",
        json={
            "client_request_id": f"{request_id}-package-commit",
            "session_id": gate_b.json()["session_id"],
            "material_preview_id": material["material_preview_id"],
            "material_preview_hash": material["material_preview_hash"],
            "package_review_preview_hash": preview_body["package_review_preview_hash"],
            "contract_hash": preview_body["contract_hash"],
            "expected_package_kinds": ["canonical_internal", "user_facing", "review_facing"],
        },
    )
    assert commit.status_code == 200, commit.text
    return gate_b.json(), material, preview_body, commit.json(), source


def _submit_mixed_package_review(
    client: TestClient,
    tmp_path,
    *,
    request_id: str,
) -> tuple[dict, dict, dict, dict, dict, dict]:
    gate_b, material, preview_body, commit_body, source = _construct_mixed_package_set(
        client,
        tmp_path,
        request_id=request_id,
    )
    submit = client.post(
        "/api/v1/layer3/package/review/submit",
        json={
            "client_request_id": f"{request_id}-package-submit",
            "session_id": gate_b["session_id"],
            "material_preview_id": material["material_preview_id"],
            "material_preview_hash": material["material_preview_hash"],
            "package_review_preview_hash": commit_body["package_review_preview_hash"],
            "contract_hash": commit_body["contract_hash"],
            "construction_basis_hash": commit_body["construction_basis_hash"],
            "reconciliation_record_id": commit_body["reconciliation_record_id"],
            "output_package_ids": commit_body["output_package_ids"],
            "payload_hashes": commit_body["payload_hashes"],
            "operator_decision": "approved",
            "expected_package_kinds": ["canonical_internal", "user_facing", "review_facing"],
        },
    )
    assert submit.status_code == 200, submit.text
    return gate_b, material, preview_body, commit_body, submit.json(), source


def _mixed_handoff_export_prepare_payload(
    *,
    request_id: str,
    gate_b: dict,
    material: dict,
    commit_body: dict,
    submit_body: dict,
    operator_decision: str = "authorize_prepare",
    decision_notes: str | None = None,
) -> dict:
    payload = {
        "client_request_id": request_id,
        "session_id": gate_b["session_id"],
        "material_preview_id": material["material_preview_id"],
        "material_preview_hash": material["material_preview_hash"],
        "package_review_preview_hash": commit_body["package_review_preview_hash"],
        "contract_hash": commit_body["contract_hash"],
        "construction_basis_hash": commit_body["construction_basis_hash"],
        "reconciliation_record_id": commit_body["reconciliation_record_id"],
        "output_package_ids": commit_body["output_package_ids"],
        "payload_hashes": commit_body["payload_hashes"],
        "package_review_submit_record_ref": submit_body["submit_record_ref"],
        "package_review_state": submit_body["package_review_state"],
        "handoff_target": "mixed_source_review_package",
        "export_mode": "reference_envelope_only",
        "operator_decision": operator_decision,
        "expected_package_kinds": ["canonical_internal", "user_facing", "review_facing"],
    }
    if decision_notes is not None:
        payload["decision_notes"] = decision_notes
    return payload


