def test_layer3_api_validates_sec_edgar_real_company_corpus_product_path(
    client: TestClient,
    tmp_path,
    monkeypatch,
) -> None:
    monkeypatch.setattr(settings, "layer3_sec_edgar_arelle_fact_authority_cutover_enabled", False)
    monkeypatch.setattr(settings, "layer3_sec_edgar_user_agent", "Layer3 Test contact@example.com")
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "SEC_EDGAR_SLEEP", lambda _seconds: None)
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "_enforce_rate_limit", lambda: None)
    fake_client = _FakeSecEdgarClient(_real_company_validation_fake_results())
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "SEC_EDGAR_CLIENT", fake_client)

    response = client.post(
        "/api/v1/layer3/source/sec-edgar/real-company-corpus/validation",
        json={
            "client_request_id": "sec-edgar-real-company-validation-001",
            "validation_mode": "sec_edgar_real_company_corpus_validation_v1",
            "operator_decision": "validate_sec_edgar_real_company_corpus_product_path",
            "company_matrix": ["MSFT", "STLD", "SONY", "CCJ"],
            "operator_confirmation": True,
        },
    )

    assert response.status_code == 200, response.text
    body = response.json()
    assert body["schema_id"] == "layer3.sec_edgar_real_company_corpus_validation.v1"
    assert body["validation_state"] == "sec_edgar_real_company_corpus_validation_ready"
    assert body["company_matrix"] == ["MSFT", "STLD", "SONY", "CCJ"]
    assert body["filing_selection_policy"] == "real_company_recent_annual_and_interim_or_current_v1"
    assert body["diagnostics"]["real_company_count"] == 4
    assert body["diagnostics"]["filing_count"] == 8
    assert body["diagnostics"]["supported_count"] == 8
    assert body["diagnostics"]["generic_text_downgrade_performed"] is False
    assert body["diagnostics"]["candidate_b_pdf_only_routing_performed"] is False
    assert body["diagnostics"]["product_quality_matrix_recorded"] is True
    assert body["diagnostics"]["financial_statement_semantics_finalized"] is False
    assert body["diagnostics"]["cross_company_comparability_admitted"] is False
    assert {record["form_type"] for record in body["filing_validation_records"]} >= {
        "10-K",
        "10-Q",
        "8-K",
        "20-F",
        "40-F",
        "6-K",
    }
    assert all(
        "handoff_export_prepare" in record["outputs_produced"]
        for record in body["filing_validation_records"]
    )
    assert all(record["authority_hashes"]["handoff_export_prepare_receipt_hash"] for record in body["filing_validation_records"])
    assert len(body["product_quality_matrix"]) == 8
    assert all(
        record["quality_assessment_status"] == "redacted_quality_evidence_ready_with_known_semantic_gaps"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["financial_statement_semantics"] == "bounded_profile_available_not_finalized"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["period_unit_context_dimension_profile"]
        == "bounded_hash_profile_available_not_resolved"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["statement_role_quality_profile"]
        == "bounded_role_rule_profile_available_not_semantics_finalized"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["extension_taxonomy_retention_profile"]
        == "bounded_hash_profile_available_unmapped"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["standard_concept_mapping_profile"]
        == "bounded_standard_concept_profile_available_not_normalized"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["fact_deduplication_conflict_diagnostics"]
        == "bounded_diagnostics_available_not_deduplicated_or_resolved"
        for record in body["product_quality_matrix"]
    )
    assert all(
        record["quality_dimensions"]["cross_company_comparability_readiness_audit"]
        == "bounded_readiness_audit_available_not_comparable"
        for record in body["product_quality_matrix"]
    )
    assert {
        record["quality_dimensions"]["cross_company_comparability"]
        for record in body["product_quality_matrix"]
    } <= {"standard_taxonomy_profile_available_not_admitted", "not_admitted"}
    assert any(
        record["quality_dimensions"]["cross_company_comparability"]
        == "standard_taxonomy_profile_available_not_admitted"
        for record in body["product_quality_matrix"]
    )
    assert all(
        "cross_company_comparability_not_admitted" in record["quality_gaps"]
        for record in body["product_quality_matrix"]
    )
    assert {
        record["form_family"]
        for record in body["product_quality_matrix"]
        if record["quality_dimensions"]["extension_fact_handling"] == "retained_redacted"
    } >= {"20-F", "40-F", "6-K"}
    assert all(
        record["quality_evidence"]["quality_metrics"]["semantic_profile_assigned_count"]
        == record["quality_evidence"]["quality_metrics"]["fact_count"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["period_unit_context_dimension_profile_assigned_count"]
        == record["quality_evidence"]["quality_metrics"]["fact_count"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["statement_role_quality_profile_assigned_count"]
        == record["quality_evidence"]["quality_metrics"]["fact_count"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["extension_taxonomy_retention_profile_assigned_count"]
        == record["quality_evidence"]["quality_metrics"]["fact_count"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["standard_concept_mapping_profile_assigned_count"]
        == record["quality_evidence"]["quality_metrics"]["fact_count"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["period_unit_context_dimension_profile_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["statement_role_quality_profile_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["extension_taxonomy_retention_profile_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["standard_concept_mapping_profile_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["fact_deduplication_conflict_diagnostics_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["cross_company_comparability_readiness_audit_hash"]
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["cross_company_comparability_readiness_status"]
        == "bounded_readiness_audit_available_not_comparable"
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["cross_company_comparability_ready"] is False
        for record in body["filing_validation_records"]
    )
    assert all(
        record["quality_evidence"]["quality_metrics"]["fact_deduplication_performed"] is False
        and record["quality_evidence"]["quality_metrics"]["fact_conflict_resolution_performed"] is False
        and record["quality_evidence"]["quality_metrics"]["fact_values_dropped"] is False
        for record in body["filing_validation_records"]
    )
    assert any(
        record["quality_evidence"]["quality_metrics"]["company_extension_unmapped_count"] > 0
        for record in body["filing_validation_records"]
    )
    assert len(fake_client.calls) == 12
    assert fake_client.calls[0]["url"] == "https://data.sec.gov/submissions/CIK0000789019.json"
    assert "https://www.sec.gov" not in response.text
    assert "https://data.sec.gov" not in response.text
    assert "0000789019-25-000100" not in response.text
    assert "Microsoft Corporation" not in response.text
    assert "Business overview" not in response.text
    assert "value_text" not in response.text
    _assert_raw_string_not_projected(body, "123")
    assert str(tmp_path) not in response.text

    replay_response = client.post(
        "/api/v1/layer3/source/sec-edgar/real-company-corpus/validation",
        json={
            "client_request_id": "sec-edgar-real-company-validation-001",
            "validation_mode": "sec_edgar_real_company_corpus_validation_v1",
            "operator_decision": "validate_sec_edgar_real_company_corpus_product_path",
            "company_matrix": ["MSFT", "STLD", "SONY", "CCJ"],
            "operator_confirmation": True,
        },
    )
    assert replay_response.status_code == 200, replay_response.text
    assert replay_response.json()["cache"]["idempotent_replay"] is True
    assert replay_response.json()["validation_receipt_hash"] == body["validation_receipt_hash"]
    assert len(fake_client.calls) == 12

    status_response = client.get(
        "/api/v1/layer3/source/sec-edgar/real-company-corpus/validation/status/"
        f"{body['validation_receipt_id']}"
    )
    assert status_response.status_code == 200, status_response.text
    assert status_response.json()["schema_id"] == "layer3.sec_edgar_real_company_corpus_validation_status.v1"
    assert status_response.json()["validation_receipt_hash"] == body["validation_receipt_hash"]
    assert "https://www.sec.gov" not in status_response.text
    assert str(tmp_path) not in status_response.text


def test_layer3_api_default_arelle_cutover_does_not_invoke_arelle_in_corpus_validation_without_corpus_flag(
    client: TestClient,
    monkeypatch,
) -> None:
    assert settings.layer3_sec_edgar_arelle_fact_authority_cutover_enabled is True
    assert settings.layer3_sec_edgar_arelle_corpus_validation_enabled is False

    def _unexpected_arelle_run(*_args, **_kwargs):
        raise AssertionError("corpus validation must not invoke Arelle without explicit corpus-validation flag")

    monkeypatch.setattr(layer3_sec_xbrl_sidecar, "ARELLE_SUBPROCESS_RUNNER", _unexpected_arelle_run)
    monkeypatch.setattr(settings, "layer3_sec_edgar_user_agent", "Layer3 Test contact@example.com")
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "SEC_EDGAR_SLEEP", lambda _seconds: None)
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "_enforce_rate_limit", lambda: None)
    fake_client = _FakeSecEdgarClient(_real_company_validation_fake_results())
    monkeypatch.setattr(layer3_sec_edgar_live_source_artifact, "SEC_EDGAR_CLIENT", fake_client)

    response = client.post(
        "/api/v1/layer3/source/sec-edgar/real-company-corpus/validation",
        json={
            "client_request_id": "sec-edgar-real-company-validation-no-default-arelle",
            "validation_mode": "sec_edgar_real_company_corpus_validation_v1",
            "operator_decision": "validate_sec_edgar_real_company_corpus_product_path",
            "company_matrix": ["MSFT", "STLD", "SONY", "CCJ"],
            "operator_confirmation": True,
        },
    )

    assert response.status_code == 200, response.text
    body = response.json()
    assert body["validation_state"] == "sec_edgar_real_company_corpus_validation_ready"
    assert all(
        "arelle_resolved_fact_authority_sidecar" not in record["outputs_produced"]
        for record in body["filing_validation_records"]
    )


