def test_layer3_api_records_sec_edgar_html_inline_xbrl_fact_material_downstream_proof(
    client: TestClient,
    tmp_path,
    monkeypatch,
) -> None:
    proof_request, parser, fact_authority, bridge, gate_b = (
        _prepare_sec_edgar_html_inline_xbrl_fact_material_downstream_proof_request(
            client,
            monkeypatch,
            label="fact-proof-001",
        )
    )

    response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json=proof_request,
    )

    assert response.status_code == 200, response.text
    body = response.json()
    assert body["schema_id"] == "layer3.sec_edgar_html_inline_xbrl_fact_material_downstream_proof.v1"
    assert body["proof_state"] == "sec_edgar_html_inline_xbrl_fact_material_downstream_layer3_e2e_proven"
    assert body["source_family"] == "sec_edgar_html_inline_xbrl"
    assert body["parser_family"] == "sec_edgar_html_inline_xbrl_source_family_parser_v1"
    assert body["typed_content_contract_id"] == "sec_edgar_html_inline_xbrl_fact_material_units_v1"
    assert body["parser_receipt_hash"] == parser["parser_receipt_hash"]
    assert body["fact_authority_receipt_hash"] == fact_authority["fact_authority_receipt_hash"]
    assert body["fact_inventory_hash"] == fact_authority["fact_inventory_hash"]
    assert body["diagnostics_hash"] == fact_authority["diagnostics_hash"]
    assert body["fact_material_bridge_receipt_hash"] == bridge["fact_material_bridge_receipt_hash"]
    assert body["bridge_receipt_hash"] == bridge["bridge_receipt_hash"]
    assert body["session_id"] == gate_b["session_id"]
    assert set(body["coverage"]) == set(proof_request["coverage_evidence"])
    assert "html_inline_xbrl_fact_authority" in body["coverage"]
    assert "html_inline_xbrl_fact_material_authority_bridge" in body["coverage"]
    assert body["raw_local_path_exposed"] is False
    assert body["raw_url_exposed"] is False
    assert body["artifact_bytes_exposed"] is False
    assert body["negative_invariants"]["fact_value_reconstruction_admitted_in_proof"] is False
    assert body["negative_invariants"]["sec_companyfacts_api_runtime_enabled"] is False
    assert body["negative_invariants"]["taxonomy_network_resolution_enabled"] is False
    assert body["negative_invariants"]["financial_statement_semantics_admitted"] is False
    assert body["negative_invariants"]["fact_to_statement_classification_enabled"] is False
    assert body["negative_invariants"]["raw_fact_values_exposed_in_operator_projection"] is False
    assert body["provider_object_writes_enabled"] is False
    assert body["connector_dispatch_enabled"] is False
    assert "https://www.sec.gov" not in response.text
    assert "aapl-20240928.htm" not in response.text
    assert "value_text" not in response.text
    assert "Company narrative" not in response.text
    assert str(tmp_path) not in response.text


def test_layer3_api_rejects_sec_edgar_html_inline_xbrl_fact_material_downstream_proof_stale_or_unsafe(
    client: TestClient,
    tmp_path,
    monkeypatch,
) -> None:
    proof_request, _parser, _fact_authority, _bridge, _gate_b = (
        _prepare_sec_edgar_html_inline_xbrl_fact_material_downstream_proof_request(
            client,
            monkeypatch,
            label="fact-proof-reject",
        )
    )

    stale_fact_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json={**proof_request, "fact_authority_receipt_hash": "f" * 64},
    )
    assert stale_fact_response.status_code == 409, stale_fact_response.text
    assert stale_fact_response.json()["error_code"] == "sec_edgar_html_inline_xbrl_fact_authority_receipt_hash_mismatch"

    stale_bridge_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json={**proof_request, "fact_material_bridge_receipt_hash": "e" * 64},
    )
    assert stale_bridge_response.status_code == 409, stale_bridge_response.text
    assert stale_bridge_response.json()["error_code"] == (
        "sec_edgar_html_inline_xbrl_fact_material_downstream_proof_bridge_hash_mismatch"
    )

    missing_coverage = dict(proof_request["coverage_evidence"])
    missing_coverage.pop("html_inline_xbrl_fact_authority")
    missing_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json={**proof_request, "coverage_evidence": missing_coverage},
    )
    assert missing_response.status_code == 409, missing_response.text
    assert missing_response.json()["error_code"] == (
        "sec_edgar_html_inline_xbrl_fact_material_downstream_proof_coverage_incomplete"
    )

    unsafe_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json={**proof_request, "raw_url": "https://www.sec.gov/raw"},
    )
    assert unsafe_response.status_code == 400, unsafe_response.text
    assert unsafe_response.json()["error_code"] == (
        "sec_edgar_html_inline_xbrl_fact_material_downstream_proof_forbidden_request_fields"
    )
    assert "https://www.sec.gov/raw" not in unsafe_response.text

    unsafe_coverage = copy.deepcopy(proof_request["coverage_evidence"])
    assert isinstance(unsafe_coverage, dict)
    unsafe_coverage["gate_b_commit"]["value_text"] = "123"
    unsafe_coverage_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json={**proof_request, "coverage_evidence": unsafe_coverage},
    )
    assert unsafe_coverage_response.status_code == 400, unsafe_coverage_response.text
    assert unsafe_coverage_response.json()["error_code"] == (
        "sec_edgar_html_inline_xbrl_fact_material_downstream_proof_forbidden_request_fields"
    )
    _assert_raw_string_not_projected(unsafe_coverage_response.json(), "123")

    db = client.layer3_session_factory()
    try:
        snapshot = (
            db.query(L3MaterialSnapshot)
            .filter(L3MaterialSnapshot.payload_hash == proof_request["material_snapshot_payload_hash"])
            .one()
        )
        snapshot.payload_ref = str(tmp_path / "raw-local-fact-material.json")
        db.commit()
    finally:
        db.close()
    missing_payload_response = client.post(
        "/api/v1/layer3/source/sec-edgar/html-inline-xbrl/fact-authority/material-bridge/downstream-proof",
        json=proof_request,
    )
    assert missing_payload_response.status_code == 409, missing_payload_response.text
    assert (
        missing_payload_response.json()["error_code"]
        == "sec_edgar_html_inline_xbrl_fact_material_downstream_proof_material_snapshot_payload_missing"
    )
    assert str(tmp_path) not in missing_payload_response.text
    assert "raw-local-fact-material.json" not in missing_payload_response.text


