def test_layer3_api_provider_private_signed_url_openapi_prepare_status_schema(client: TestClient) -> None:
    spec = client.get("/openapi.json").json()
    prepare_path = "/api/v1/layer3/handoff/export/download/provider-private-signed-url/prepare"
    status_path = (
        "/api/v1/layer3/handoff/export/download/provider-private-signed-url/status/"
        "{provider_signed_url_receipt_id}"
    )
    revoke_path = "/api/v1/layer3/handoff/export/download/provider-private-signed-url/revoke"
    local_outbox_prepare_path = "/api/v1/layer3/handoff/connector/local-outbox/provider-private/prepare"
    local_outbox_status_path = (
        "/api/v1/layer3/handoff/connector/local-outbox/provider-private/status/"
        "{provider_private_handoff_receipt_id}"
    )
    external_local_export_write_path = (
        "/api/v1/layer3/handoff/connector/local-outbox/external-local-export/write"
    )
    external_local_export_status_path = (
        "/api/v1/layer3/handoff/connector/local-outbox/external-local-export/status/"
        "{external_local_export_receipt_id}"
    )
    internal_webhook_dispatch_path = "/api/v1/layer3/handoff/export/internal-webhook/dispatch"
    internal_webhook_status_path = (
        "/api/v1/layer3/handoff/export/internal-webhook/status/"
        "{internal_webhook_dispatch_receipt_id}"
    )
    assert prepare_path in spec["paths"]
    assert status_path in spec["paths"]
    assert revoke_path in spec["paths"]
    assert local_outbox_prepare_path in spec["paths"]
    assert local_outbox_status_path in spec["paths"]
    assert external_local_export_write_path in spec["paths"]
    assert external_local_export_status_path in spec["paths"]
    assert internal_webhook_dispatch_path in spec["paths"]
    assert internal_webhook_status_path in spec["paths"]
    assert "/api/v1/layer3/handoff/export/download/provider-private-signed-url/use" not in spec["paths"]

    prepare_schema = spec["paths"][prepare_path]["post"]["requestBody"]["content"]["application/json"]["schema"]
    assert prepare_schema["additionalProperties"] is False
    assert set(prepare_schema["required"]) == {
        "client_request_id",
        "session_id",
        "analysis_plan_id",
        "pass_run_id",
        "reconciliation_record_id",
        "external_export_download_record_ref",
        "export_download_descriptor_ref",
        "external_export_download_state",
        "export_download_target",
        "download_mode",
        "delivery_mode",
        "operator_decision",
        "source_artifact_hash",
        "source_artifact_size_bytes",
        "recipient_scope",
    }
    assert prepare_schema["properties"]["delivery_mode"]["enum"] == ["provider_private_signed_url"]
    assert prepare_schema["properties"]["operator_decision"]["enum"] == ["prepare_provider_private_signed_url"]
    assert prepare_schema["properties"]["requested_ttl_seconds"]["maximum"] == 900
    for forbidden in (
        "provider_credentials",
        "provider_secret",
        "provider_object_key",
        "provider_url",
        "public_url",
        "public_proxy_url",
        "download_url",
        "signed_reference_token",
        "connector_dispatch",
        "provider_private_signed_url_token",
        "local_directory",
        "rag_vector_settings",
        "browser_durable_authority",
    ):
        assert prepare_schema["properties"][forbidden]["not"] == {}

    assert _openapi_response_schema(spec, prepare_path, "post")["title"] == (
        "Layer3ProviderPrivateSignedUrlPrepareResponse"
    )
    assert _openapi_response_schema(spec, status_path, "get")["title"] == (
        "Layer3ProviderPrivateSignedUrlStatusResponse"
    )
    revoke_schema = spec["paths"][revoke_path]["post"]["requestBody"]["content"]["application/json"]["schema"]
    assert revoke_schema["additionalProperties"] is False
    assert set(revoke_schema["required"]) == {
        "client_request_id",
        "provider_signed_url_receipt_id",
        "idempotency_key",
        "revoked_by",
        "revocation_reason",
        "operator_decision",
    }
    assert revoke_schema["properties"]["operator_decision"]["enum"] == ["revoke_provider_private_signed_url"]
    for forbidden in (
        "provider_private_signed_url_token",
        "raw_provider_private_signed_url_token",
        "provider_url",
        "provider_credentials",
        "public_url",
        "connector_dispatch",
        "destination_id",
    ):
        assert revoke_schema["properties"][forbidden]["not"] == {}
    assert _openapi_response_schema(spec, revoke_path, "post")["title"] == (
        "Layer3ProviderPrivateSignedUrlRevokeResponse"
    )
    local_outbox_prepare_schema = spec["paths"][local_outbox_prepare_path]["post"]["requestBody"]["content"][
        "application/json"
    ]["schema"]
    assert local_outbox_prepare_schema["additionalProperties"] is False
    assert set(local_outbox_prepare_schema["required"]) == {
        "client_request_id",
        "session_id",
        "analysis_plan_id",
        "pass_run_id",
        "reconciliation_record_id",
        "connector_dispatch_record_ref",
        "connector_local_destination_receipt_id",
        "server_owned_local_outbox_target_receipt_id",
        "server_owned_local_outbox_write_receipt_id",
        "external_export_download_record_ref",
        "target_identity",
        "dispatch_mode",
        "operator_decision",
        "recipient_scope",
    }
    assert local_outbox_prepare_schema["properties"]["target_identity"]["enum"] == [
        "server_owned_local_outbox_provider_private_handoff_destination"
    ]
